#!/bin/bash

# Script to log keyboard inputs and active application for LLM training
# This uses xinput for keylogging and wmctrl for active window detection.
# Run this script with root privileges if needed (e.g., sudo ./keylogger.sh)
# It logs to a file named 'keylog.txt' in the current directory.
# Press Ctrl+C to stop logging.

LOG_FILE="keylog.txt"
DEVICE_ID=$(xinput list | grep -i keyboard | head -1 | sed 's/.*id=\$[0-9]*\$.*/\1/')

if [ -z "$DEVICE_ID" ]; then
    echo "No keyboard device found. Exiting."
    exit 1
fi

echo "Starting keylogger on device ID: $DEVICE_ID"
echo "Logging to: $LOG_FILE"
echo "Press Ctrl+C to stop."

